public static KeyWrapper getKeyWrapper(JWK jwk) {
  try {
    JWKParser parser = JWKParser.create(jwk);
    if (parser.isKeyTypeSupported(jwk.getKeyType())) {
      return wrap(jwk, parser);
    }
    else {
      return null;
    }
  } catch (RuntimeException e) {
    // 处理运行时异常，如记录日志或转换为更适合业务场景的异常
    throw e;
  }
}
